313: function buildSpeedoTicks() {
314:   const NS = 'http://www.w3.org/2000/svg';
315:   for (let i = 0; i <= 8; i++) {
316:     const a = Math.PI + (i / 8) * Math.PI;
317:     const r1 = 74, r2 = i % 2 === 0 ? 63 : 68;
318:     const line = document.createElementNS(NS, 'line');
319:     line.setAttribute('x1', 100 + Math.cos(a) * r1);
320:     line.setAttribute('y1', 108 + Math.sin(a) * r1);
321:     line.setAttribute('x2', 100 + Math.cos(a) * r2);
322:     line.setAttribute('y2', 108 + Math.sin(a) * r2);
323:     dom.speedoTicks.appendChild(line);
324:   }
325: }
