365: function drawMenuMinimap(last) {
366:   const canvas = dom.menuMinimap;
367:   const ctx = canvas.getContext('2d');
368:   const w = canvas.width, h = canvas.height;
369:   ctx.clearRect(0, 0, w, h);
370:   ctx.fillStyle = 'rgba(5,7,10,.4)';
371:   ctx.fillRect(0, 0, w, h);
372: 
373:   // faint grid
374:   ctx.strokeStyle = 'rgba(255,255,255,.035)';
375:   ctx.lineWidth = 1;
376:   for (let x = 20; x < w; x += 42) {
377:     ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
378:   }
379:   for (let y = 16; y < h; y += 42) {
380:     ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
381:   }
382: 
383:   if (!last) {
384:     ctx.save();
385:     ctx.translate(w / 2, h / 2);
386:     ctx.setLineDash([4, 10]);
387:     ctx.strokeStyle = 'rgba(255,77,31,.28)';
388:     ctx.lineWidth = 1.5;
389:     ctx.beginPath();
390:     ctx.ellipse(0, 0, w * 0.33, h * 0.27, -0.18, 0, TAU);
391:     ctx.stroke();
392:     ctx.setLineDash([]);
393:     ctx.strokeStyle = 'rgba(255,255,255,.08)';
394:     ctx.beginPath(); ctx.moveTo(-9, 0); ctx.lineTo(9, 0); ctx.moveTo(0, -9); ctx.lineTo(0, 9); ctx.stroke();
395:     ctx.restore();
396:     return;
397:   }
398: 
399:   const preview = analyzePreview(last.points, { targetLength: 1900 });
400:   if (!preview.prepared.length) return;
401:   let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
402:   for (const p of preview.prepared) {
403:     minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
404:     minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
405:   }
406:   const pad = 30;
407:   const scale = Math.min((w - pad * 2) / (maxX - minX || 1), (h - pad * 2) / (maxY - minY || 1));
408:   const ox = (w - (maxX - minX) * scale) / 2 - minX * scale;
409:   const oy = (h - (maxY - minY) * scale) / 2 - minY * scale;
410:   const map = (p) => ({ x: p.x * scale + ox, y: p.y * scale + oy });
411: 
412:   ctx.save();
413:   ctx.lineJoin = 'round';
414:   ctx.lineCap = 'round';
415:   ctx.beginPath();
416:   preview.prepared.forEach((p, i) => {
417:     const q = map(p);
418:     if (i === 0) ctx.moveTo(q.x, q.y); else ctx.lineTo(q.x, q.y);
419:   });
420:   ctx.closePath();
421:   ctx.strokeStyle = 'rgba(255,77,31,.16)';
422:   ctx.lineWidth = 13;
423:   ctx.shadowColor = 'rgba(255,77,31,.7)';
424:   ctx.shadowBlur = 18;
425:   ctx.stroke();
426:   ctx.shadowBlur = 0;
427:   ctx.strokeStyle = 'rgba(7,9,12,.9)';
428:   ctx.lineWidth = 7;
429:   ctx.stroke();
430:   ctx.strokeStyle = '#f3efe5';
431:   ctx.lineWidth = 2.4;
432:   ctx.stroke();
433: 
434:   // start marker
435:   const start = map(preview.prepared[0]);
436:   ctx.fillStyle = '#ff4d1f';
437:   ctx.beginPath();
438:   ctx.arc(start.x, start.y, 3.5, 0, TAU);
439:   ctx.fill();
440:   ctx.strokeStyle = 'rgba(255,77,31,.8)';
441:   ctx.lineWidth = 1;
442:   ctx.beginPath();
443:   ctx.arc(start.x, start.y, 8, 0, TAU);
444:   ctx.stroke();
445:   ctx.restore();
446: }
