877: /* ═══════════════════════════════════════════════════════════════════
878:    Smoke / dust particles
879:    ═══════════════════════════════════════════════════════════════════ */
880: class SmokeSystem {
881:   constructor(scene) {
882:     this.count = 260;
883:     this.cursor = 0;
884:     this.positions = new Float32Array(this.count * 3);
885:     this.colors = new Float32Array(this.count * 3);
886:     this.sizes = new Float32Array(this.count);
887:     this.alphas = new Float32Array(this.count);
888:     this.life = new Float32Array(this.count);
889:     this.maxLife = new Float32Array(this.count);
890:     this.vel = new Float32Array(this.count * 3);
891:     this.baseSize = new Float32Array(this.count);
892:     for (let i = 0; i < this.count; i++) {
893:       this.positions[i * 3 + 1] = -999;
894:       this.alphas[i] = 0;
895:     }
896:     const geo = new THREE.BufferGeometry();
897:     geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
898:     geo.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3));
899:     geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
900:     geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));
901:     this.geo = geo;
902:     this.material = new THREE.ShaderMaterial({
903:       transparent: true,
904:       depthWrite: false,
905:       vertexShader: `
906:         attribute float aSize;
907:         attribute float aAlpha;
908:         attribute vec3 aColor;
909:         varying float vAlpha;
910:         varying vec3 vColor;
911:         void main() {
912:           vAlpha = aAlpha;
913:           vColor = aColor;
914:           vec4 mv = modelViewMatrix * vec4(position, 1.0);
915:           gl_PointSize = aSize * (340.0 / max(1.0, -mv.z));
916:           gl_Position = projectionMatrix * mv;
917:         }
918:       `,
919:       fragmentShader: `
920:         varying float vAlpha;
921:         varying vec3 vColor;
922:         void main() {
923:           float d = length(gl_PointCoord - vec2(0.5));
924:           if (d > 0.5) discard;
925:           gl_FragColor = vec4(vColor, vAlpha * smoothstep(0.5, 0.08, d));
926:         }
927:       `
928:     });
929:     this.points = new THREE.Points(geo, this.material);
930:     this.points.frustumCulled = false;
931:     scene.add(this.points);
932:     this.dirty = false;
933:   }
934: 
935:   emit(x, y, z, color, size = 0.55, life = 1.1, spread = 1.4) {
936:     const i = this.cursor;
937:     this.cursor = (this.cursor + 1) % this.count;
938:     this.positions[i * 3] = x + (Math.random() - 0.5) * 0.5;
939:     this.positions[i * 3 + 1] = y + Math.random() * 0.2;
940:     this.positions[i * 3 + 2] = z + (Math.random() - 0.5) * 0.5;
941:     this.colors[i * 3] = color.r;
942:     this.colors[i * 3 + 1] = color.g;
943:     this.colors[i * 3 + 2] = color.b;
944:     this.vel[i * 3] = (Math.random() - 0.5) * spread;
945:     this.vel[i * 3 + 1] = 0.4 + Math.random() * spread;
946:     this.vel[i * 3 + 2] = (Math.random() - 0.5) * spread;
947:     this.life[i] = life;
948:     this.maxLife[i] = life;
949:     this.baseSize[i] = size;
950:     this.sizes[i] = size;
951:     this.alphas[i] = 0.5;
952:     this.dirty = true;
953:   }
954: 
955:   update(dt) {
956:     for (let i = 0; i < this.count; i++) {
957:       if (this.life[i] <= 0) continue;
958:       this.life[i] -= dt;
959:       if (this.life[i] <= 0) {
960:         this.alphas[i] = 0;
961:         this.positions[i * 3 + 1] = -999;
962:         this.dirty = true;
963:         continue;
964:       }
965:       const k = this.life[i] / this.maxLife[i];
966:       this.positions[i * 3] += this.vel[i * 3] * dt;
967:       this.positions[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
968:       this.positions[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
969:       this.vel[i * 3] *= 0.985;
970:       this.vel[i * 3 + 2] *= 0.985;
971:       this.vel[i * 3 + 1] += dt * 0.2;
972:       this.sizes[i] = this.baseSize[i] * (1.6 - k * 0.6);
973:       this.alphas[i] = k * 0.42;
974:       this.dirty = true;
975:     }
976:     if (this.dirty) {
977:       this.geo.attributes.position.needsUpdate = true;
978:       this.geo.attributes.aColor.needsUpdate = true;
979:       this.geo.attributes.aSize.needsUpdate = true;
980:       this.geo.attributes.aAlpha.needsUpdate = true;
981:       this.dirty = false;
982:     }
983:   }
984: 
985:   reset() {
986:     for (let i = 0; i < this.count; i++) {
987:       this.life[i] = 0;
988:       this.alphas[i] = 0;
989:       this.positions[i * 3 + 1] = -999;
990:     }
991:     this.geo.attributes.position.needsUpdate = true;
