2454: // Keep the field from driving through itself. Cars that are side by side stay a
2455: // car's width apart; a car that is still directly behind lifts and tucks in.
2456: function separateAiCars(ai, limit) {
2457:   for (let i = 0; i < ai.length; i++) {
2458:     const a = ai[i];
2459:     for (let j = i + 1; j < ai.length; j++) {
2460:       const b = ai[j];
2461:       const d = b.dist - a.dist;
2462:       if (Math.abs(d) > 5.2) continue;
2463:       const sideGap = b.lateral - a.lateral;
2464:       if (Math.abs(sideGap) >= AI_MIN_SIDE_GAP) continue;
2465:       const side = Math.sign(sideGap) || (a.passSide || 1);
2466:       const push = (AI_MIN_SIDE_GAP - Math.abs(sideGap)) * 0.5;
2467:       a.lateral = clamp(a.lateral - side * push, -limit, limit);
2468:       b.lateral = clamp(b.lateral + side * push, -limit, limit);
2469:       if (Math.abs(b.lateral - a.lateral) < 1.85) {
2470:         const front = d > 0 ? b : a;
