2537: // AI pit lane procedure: brake for the limiter, turn left into the team's box,
2538: // stop for service, then merge back onto the through-lane and rejoin the track.
2539: function updateAiPit(dt, a) {
2540:   const pit = a.pit;
2541:   const box = a.pitBox;
2542:   const routeLength = race.world.pitRouteLength ?? 380;
2543: 
2544:   if (pit.phase === 'in') {
2545:     const remaining = Math.max(0, box.routeProgress - pit.routeProgress);
2546:     let target = Math.min(PIT_LIMITER_SPEED, Math.sqrt(remaining * 9.5) + 1.2);
2547:     target = aiPitFollowSpeed(a, target);
2548:     if (pit.speed < target) pit.speed = Math.min(target, pit.speed + 9 * dt);
2549:     else pit.speed = Math.max(target, pit.speed - 26 * dt);
2550:     pit.routeProgress = Math.min(box.routeProgress, pit.routeProgress + pit.speed * dt);
2551:     if (pit.routeProgress >= box.routeProgress - 0.35 && pit.speed <= 2.4) {
2552:       pit.routeProgress = box.routeProgress;
2553:       pit.speed = 0;
2554:       pit.phase = 'service';
2555:       pit.serviceTimer = pit.serviceDuration;
2556:     }
2557:   } else if (pit.phase === 'service') {
2558:     pit.speed = 0;
2559:     pit.serviceTimer = Math.max(0, pit.serviceTimer - dt);
2560:     if (pit.serviceTimer <= 0) {
2561:       pit.phase = 'out';
2562:       pit.stops++;
2563:       a.tyreStops = (a.tyreStops || 0) + 1;
2564:     }
2565:   } else if (pit.phase === 'out') {
2566:     const remaining = Math.max(0, routeLength - pit.routeProgress);
2567:     let target = Math.min(PIT_LIMITER_SPEED, 9 + Math.sqrt(remaining * 4.5));
2568:     target = aiPitFollowSpeed(a, target);
2569:     if (pit.speed < target) pit.speed = Math.min(target, pit.speed + 8 * dt);
2570:     else pit.speed = Math.max(target, pit.speed - 20 * dt);
2571:     pit.routeProgress = Math.min(routeLength, pit.routeProgress + pit.speed * dt);
2572:     if (pit.routeProgress >= routeLength - 0.8) {
2573:       pit.routeProgress = routeLength;
2574:       pit.phase = 'done';
2575:       pit.speed = Math.min(PIT_LIMITER_SPEED, pit.speed);
2576:       a.dist = pit.entryDist + routeLength;
2577:       a.lateral = 0;
2578:       a.passLat = 0;
2579:       a.passSide = 0;
2580:       a.passUntil = 0;
2581:     }
2582:   }
2583: 
2584:   a.dist = pit.entryDist + pit.routeProgress;
2585:   a.speed = pit.speed;
2586: 
2587:   if (pit.phase === 'service') {
2588:     pit.x = box.x;
2589:     pit.z = box.z;
2590:     pit.yaw = box.yaw;
2591:     pit.steer = 0;
2592:   } else {
2593:     const here = pitPathPoint(pit.routeProgress, pit.phase === 'in' ? 'in' : 'out', box.routeProgress, pit.entryLateral || 0);
2594:     pit.x = here.x;
2595:     pit.z = here.z;
2596:     pit.yaw = pitPathYaw(pit.routeProgress, pit.phase === 'in' ? 'in' : 'out', box.routeProgress, pit.entryLateral || 0);
2597:     const lookYaw = pitPathYaw(
2598:       Math.min(routeLength, pit.routeProgress + 9),
2599:       pit.phase === 'in' ? 'in' : 'out',
2600:       box.routeProgress,
2601:       pit.entryLateral || 0
2602:     );
2603:     pit.steer = clamp(Math.atan2(Math.sin(lookYaw - pit.yaw), Math.cos(lookYaw - pit.yaw)) * 1.7, -0.5, 0.5);
2604:   }
2605:   a.lastX = pit.x;
2606:   a.lastZ = pit.z;
2607:   a.lastYaw = pit.yaw;
2608: }
