2610: function updateAI(dt) {
2611:   const tr = race.track;
2612:   const L = tr.length;
2613:   const diff = DIFFICULTY[diffLevel] || DIFFICULTY.pro;
2614:   const ai = race.ai;
2615:   const limit = aiTrackLimit();
2616:   const now = race.time;
2617: 
2618:   // Update pit schedules and the cars already in the lane before building the
2619:   // racing field. Cars in the pits must not act as blockers for cars on track.
2620:   for (const a of ai) {
2621:     const pit = a.pit;
2622:     if (pit.phase === 'scheduled' && pit.entryDist - a.dist < 170) {
2623:       pit.phase = 'approach';
2624:     }
2625:     if (pit.phase === 'approach' && a.dist >= pit.entryDist) {
2626:       enterAiPit(a);
2627:     }
2628:     if (isAiInPitLane(a)) {
2629:       updateAiPit(dt, a);
2630:       a.blocker = null;
2631:       a.blockerGap = Infinity;
2632:     }
2633:   }
2634: 
2635:   const racingAi = ai.filter((a) => !isAiInPitLane(a));
2636:   // Everyone races everyone, including the player. A single grid of rivals lets
2637:   // the AI pick a side and actually fight for the place instead of following.
2638:   const p = race.player;
2639:   const field = racingAi.slice();
2640:   if (!p.finished && !isPlayerInPitLane()) {
2641:     field.push({
2642:       isPlayer: true,
2643:       name: 'YOU',
2644:       dist: p.progressDist,
2645:       lateral: p.lateral || 0,
2646:       speed: Math.abs(p.vLong),
2647:       finished: false
2648:     });
2649:   }
2650: 
2651:   // Form and mistakes give each driver a rhythm across the race. Nobody is a
2652:   // metronome, and a small error opens a real passing opportunity.
2653:   for (const a of racingAi) {
2654:     a.formTimer -= dt;
2655:     if (a.formTimer <= 0) {
2656:       a.formTimer = 6 + Math.random() * 6;
2657:       a.formTarget = 0.975 + Math.random() * 0.05;
2658:     }
2659:     a.form = damp(a.form, a.formTarget, 0.5, dt);
2660: 
2661:     a.mistakeTimer -= dt;
2662:     if (a.mistakeTimer <= 0) {
2663:       a.mistakeTimer = 13 + Math.random() * 22;
2664:       if (Math.random() < 0.45 && !a.finished) {
2665:         a.mistakeTime = 0.7 + Math.random() * 1.1;
2666:         a.mistakeSide = Math.random() < 0.5 ? -1 : 1;
2667:       }
2668:     }
2669:     if (a.mistakeTime > 0) a.mistakeTime = Math.max(0, a.mistakeTime - dt);
2670: 
2671:     const look = findAiBlocker(a, field);
2672:     a.blocker = look.blocker;
2673:     a.blockerGap = look.gap;
2674:   }
2675: 
2676:   for (const a of racingAi) planAiOvertake(a, field, limit, tr);
2677: 
2678:   for (const a of racingAi) {
2679:     const norm = ((a.dist % L) + L) % L;
2680:     const idx = Math.floor(norm / tr.step) % tr.N;
2681:     const s = tr.samples[idx];
2682:     let target = tr.speedProfile[idx] * diff.factor * a.pace * a.form;
2683: 
2684:     // Some drivers are brave in the slow stuff, others carry more through the
2685:     // fast corners. That difference is what turns a queue into a race.
2686:     const tight = clamp((Math.abs(s.k) - 1 / 170) / (1 / 55 - 1 / 170), 0, 1);
2687:     target *= lerp(a.fastBias, a.slowBias, tight);
2688: 
2689:     // Tyres fade a little over a long run, and the launch is a personal thing.
2690:     const raceFrac = clamp(a.dist / (race.totalLaps * L), 0, 1);
2691:     target *= 1 - Math.max(0, raceFrac - 0.2) * 0.022;
2692:     // Second wind / mid-race slump: a driver finds extra pace (or loses the
2693:     // tyres) for a stretch, which is what creates late-race position changes.
2694:     if (raceFrac > a.pushAt && raceFrac < a.pushAt + a.pushFor) target *= 1.038;
2695:     if (raceFrac > a.slumpAt && raceFrac < a.slumpAt + a.slumpFor) target *= 0.975;
2696:     const sinceGo = now - a.startDelay * 1000;
2697:     if (sinceGo < 0) target = 0;
2698:     else if (sinceGo < 1200) target *= clamp(0.22 + (sinceGo / 1200) * 0.92, 0, 1);
2699: 
2700:     // Slipstream: tuck in behind the car ahead and get a run on it.
2701:     if (a.blocker && a.blockerGap < 16 && !a.finished) target *= 1.018;
2702: 
2703:     // Overtake mode: once committed, the passing car leans on the car ahead and
2704:     // finishes the move instead of sitting in dirty air. The big gain arrives on
2705:     // the straights, where a slipstream pass actually happens.
2706:     if (a.passUntil > now && a.blocker && a.blockerGap < 22 && !a.finished) {
2707:       target *= Math.abs(s.k) < 1 / 120 ? 1.055 : 1.015;
2708:     }
2709: 
2710:     const latGap = a.blocker ? Math.abs(a.lateral - a.blocker.lateral) : 99;
2711:     const boxed = a.blocker && a.blockerGap < 5.0 && latGap < 2.2;
2712:     if (boxed && !a.finished) {
2713:       // Directly behind and boxed in: lift to avoid driving through the car,
2714:       // while the line logic works on getting us out of the pocket.
2715:       target = Math.min(target, Math.max(6, a.blocker.speed * 0.99));
2716:     } else if (a.blocker && latGap < 2.2 && a.blockerGap < 11 && !a.finished) {
2717:       target = Math.min(target, a.blocker.speed + (a.blockerGap - 5) * 0.55);
2718:     }
2719:     // Brake for the pit entry so the limiter engages at a believable speed.
2720:     if (a.pit.phase === 'approach' && !a.finished) {
2721:       const toEntry = Math.max(0, a.pit.entryDist - a.dist);
2722:       target = Math.min(target, Math.sqrt(PIT_LIMITER_SPEED * PIT_LIMITER_SPEED + 2 * 24 * toEntry));
2723:     }
2724:     if (a.finished) target *= 0.5;
2725: 
2726:     if (a.speed < target) a.speed = Math.min(target, a.speed + diff.accel * a.launch * dt);
2727:     else a.speed = Math.max(target, a.speed - 30 * dt);
2728:     a.dist += a.speed * dt;
2729: 
2730:     if (!a.finished && a.dist >= race.totalLaps * L) {
2731:       a.finished = true;
2732:       a.finishTime = race.time;
2733:     }
2734: 
2735:     // Choose where on the road to put the car: racing line, or a pass down one
2736:     // side. Avoid any car we are already alongside, so we never steer into it.
2737:     let targetLat = aiRacingLine(a, s, limit);
2738:     if (a.passUntil > now && !a.finished) targetLat = a.passLat;
2739:     if (a.mistakeTime > 0) targetLat = clamp(targetLat + a.mistakeSide * 1.6, -limit, limit);
2740: 
2741:     for (const b of field) {
2742:       if (b === a) continue;
2743:       const d = b.dist - a.dist;
2744:       if (Math.abs(d) > 4.8) continue;
2745:       if (Math.abs(targetLat - b.lateral) >= AI_MIN_SIDE_GAP + 0.08) continue;
2746:       const side = Math.sign(targetLat - b.lateral) || a.passSide || Math.sign(targetLat) || 1;
2747:       targetLat = clamp(b.lateral + side * (AI_MIN_SIDE_GAP + 0.08), -limit, limit);
2748:     }
2749: 
2750:     // Rate-limit the sideways move so a lane change looks like a car changing
2751:     // its line, not a snap across the circuit.
2752:     const latRate = 4.6 + a.nerve * 1.8;
2753:     a.lateral += clamp(targetLat - a.lateral, -latRate * dt, latRate * dt);
2754:     a.lateral = clamp(a.lateral, -limit, limit);
2755:   }
2756: 
2757:   separateAiCars(racingAi, limit);
2758: 
2759:   for (const a of ai) {
2760:     if (isAiInPitLane(a)) {
2761:       const pit = a.pit;
2762:       a.model.root.position.set(pit.x, 0, pit.z);
2763:       a.model.root.rotation.y = pit.yaw;
2764:       a.model.body.rotation.z = damp(a.model.body.rotation.z, 0, 6, dt);
2765:       a.model.body.rotation.x = 0;
2766:       for (const w of a.model.wheels) {
2767:         w.spin.rotation.x += (pit.speed / w.radius) * dt;
2768:         if (w.front) w.steer.rotation.y = damp(w.steer.rotation.y, pit.steer || 0, 10, dt);
2769:       }
2770:       a.model.setDRS(false);
2771:       a.model.setBrake(pit.phase === 'service' || pit.speed < 0.35);
2772:       continue;
2773:     }
2774:     const s = sampleAtDistance(tr, a.dist);
2775:     const x = s.x + s.nx * a.lateral;
2776:     const z = s.z + s.nz * a.lateral;
2777:     const yaw = Math.atan2(s.tx, s.tz);
2778:     a.lastX = x;
2779:     a.lastZ = z;
2780:     a.lastYaw = yaw;
2781:     a.model.root.position.set(x, 0, z);
2782:     a.model.root.rotation.y = yaw;
2783:     a.model.body.rotation.z = damp(a.model.body.rotation.z, clamp(-s.k * a.speed * a.speed * 0.0016, -0.06, 0.06), 6, dt);
2784:     a.model.body.rotation.x = 0;
2785:     const steer = clamp(s.k * 6 + (a.passUntil > now ? a.passSide * 0.08 : 0), -0.45, 0.45);
2786:     for (const w of a.model.wheels) {
2787:       w.spin.rotation.x += (a.speed / w.radius) * dt;
2788:       if (w.front) w.steer.rotation.y = damp(w.steer.rotation.y, steer, 10, dt);
2789:     }
2790:     const braking = a.speed > 1 && (a.blockerGap < 5.6 || Math.abs(s.k) > 1 / 95 || a.pit.phase === 'approach');
2791:     a.model.setDRS(a.speed > 58 && Math.abs(s.k) < 1 / 420);
2792:     a.model.setBrake(braking);
2793:   }
2794: }
