const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: false, executablePath: '/opt/google/chrome/chrome', args: ['--use-angle=swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3000/?demo=race&track=0', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex?.race, null, { timeout: 30000 });
await page.waitForTimeout(700);
async function snap(tag) {
  const data = await page.evaluate(() => {
    const r = window.__apex.race;
    const tr = r.track;
    const near = (x,z) => {
      let bi=0,bd=1e9;
      for (let i=0;i<tr.N;i++){const s=tr.samples[i];const d=(s.x-x)**2+(s.z-z)**2;if(d<bd){bd=d;bi=i;}}
      return {i:bi, dist: Math.sqrt(bd)};
    };
    return {
      state: r.state, time: r.time,
      player: { pos: r.player.pos, yaw: r.player.yaw, progressDist: r.player.progressDist, lastIndex: r.player.lastIndex, near: near(r.player.pos.x, r.player.pos.z) },
      ai: r.ai.map(a => ({ name: a.name, dist: a.dist, speed: a.speed, lateral: a.lateral, pos: {x:a.model.root.position.x, z:a.model.root.position.z}, yaw: a.model.root.rotation.y, near: near(a.model.root.position.x,a.model.root.position.z) }))
    };
  });
  console.log(JSON.stringify({tag, ...data}, null, 1));
}
await snap('countdown');
await page.screenshot({ path: '/tmp/opencode/grid-before.jpg', type: 'jpeg', quality: 70 });
await page.evaluate(() => { const r=window.__apex.race; r.countdownT=3.4; r.countdownStep=3; window.__apex.startRaceNow(); });
await page.waitForTimeout(120);
await snap('go+120ms');
await page.waitForTimeout(1000);
await snap('go+1120ms');
await page.screenshot({ path: '/tmp/opencode/grid-after.jpg', type: 'jpeg', quality: 70 });
await browser.close();

