await page.waitForFunction(() => window.__apex?.race, null, { timeout: 30000 });
await page.waitForTimeout(500);
const trackInfo = await page.evaluate(() => {
  const tr = window.__apex.race.track;
  const p = (i) => { const s = tr.samples[i]; return { i, x:+s.x.toFixed(2), z:+s.z.toFixed(2), tx:+s.tx.toFixed(2), tz:+s.tz.toFixed(2), yaw:+Math.atan2(s.tx,s.tz).toFixed(2) }; };
  return { N: tr.N, length: tr.length, step: tr.step, start: p(0), end: p(tr.N-1), pre: [p(tr.N-30),p(tr.N-20),p(tr.N-10),p(tr.N-1)], post: [p(0),p(1),p(10),p(20),p(30)] };
});
console.log(JSON.stringify(trackInfo, null, 1));
// tick manually 240 frames after go
await page.evaluate(() => { const r=window.__apex.race; r.countdownT=3.4; r.countdownStep=3; window.__apex.startRaceNow(); });
for (const n of [1, 30, 60, 90, 120, 180, 240, 360]) {
  await page.evaluate((count) => { for (let i=0;i<count;i++) window.__apex.tick(1/60); }, n === 1 ? 1 : 60);
