await page.evaluate(() => {
  const r = window.__apex.race;
  window.__states = [];
  let frame = 0;
  function run() {
    frame++;
    window.__states.push({
      frame, state: r.state, countdownT: r.countdownT, time: r.time,
      ai: r.ai.map(a => ({ name:a.name, dist:+a.dist.toFixed(2), x:+a.model.root.position.x.toFixed(2), z:+a.model.root.position.z.toFixed(2) })),
      player: { pd:+r.player.progressDist.toFixed(2), x:+r.player.pos.x.toFixed(2), z:+r.player.pos.z.toFixed(2) }
    });
    requestAnimationFrame(run);
  }
  requestAnimationFrame(run);
  r.countdownT = 3.15;
});
await page.waitForTimeout(7000);
const states = await page.evaluate(() => window.__states);
let lastKey = '';
for (const s of states) {
  const key = s.state + '|' + s.ai.map(a=>a.name+':'+a.dist).join(',');
  if (key !== lastKey) {
    console.log(JSON.stringify(s));
    lastKey = key;
  }
}
console.log('frames', states.length);
await browser.close();

