      ai: r.ai.length,
      meshCount,
      seatErr,
      boxChecks,
      boxY,
      before,
      afterAnchor,
      samples,
      maxLateral: maxLateral.map((v) => +v.toFixed(3)),
      distRange: r.ai.map((a, idx) => ({ name: a.name, min: +minDist[idx].toFixed(2), max: +maxDist[idx].toFixed(2) })),
      state: r.state
    };
  });

  await context.close();
  return { aiCount, trackIndex, errors, result };
}

