  const boxMax = Math.max(...r.boxChecks.map((b) => b.maxErr));
  const anchorPlayer = Math.hypot(r.afterAnchor.player.x - r.before.player.x, r.afterAnchor.player.z - r.before.player.z);
  const anchorAi = Math.max(...r.afterAnchor.ai.map((a, i) => Math.hypot(a.x - r.before.ai[i].x, a.z - r.before.ai[i].z)));
